mapper.select:
/* file : UserMapper.xml, id : findByUserId */
SELECT *, USER_PW AS PASSWORD, USER_NM AS USERNAME
  FROM TB_USER
 WHERE USER_ID            = #{id}

   AND DEL_YN      = 'N'

mapper.update:
/* file : UserMapper.xml, id : updateLastLoginDate */
UPDATE TB_USER
   SET LAST_LGN_DT = CURRENT_TIMESTAMP
 WHERE USER_SEQ        = #{userSeq}

mapper.select:
/* file : UserMapper.xml, id : getUserInfo */
  SELECT U.*, USER_ID AS ID, USER_NM AS USERNAME
    FROM TB_USER U
   WHERE U.DEL_YN      = 'N'
     AND U.USER_SEQ = #{userSeq}

mapper.insert:
/* file : UserMapper.xml, id : saveUser */
INSERT
  INTO TB_USER (
              USER_SEQ
            , USER_ID
            , USER_PW
            , USER_NM
            , USER_EML
            , USER_CONT_1
            , USER_CONT_2
            , USER_CONT_3
            , USER_HP_1
            , USER_HP_2
            , USER_HP_3
            , USER_AUTH_CD
            , REG_USER_SEQ
            , REG_IP
            )
       VALUES (
             #{userSeq}
            , LOWER(#{id})
            , #{password}
            , #{username}
            , #{userEml}
            , #{userCont1}
            , #{userCont2}
            , #{userCont3}
            , #{userHp1}
            , #{userHp2}
            , #{userHp3}
            , #{userAuthCd}
            , #{loginUserSeq}
            , #{loginUserIp}
            )

/* file : UserMapper.xml, id : saveUser */
UPDATE TB_USER
   SET USER_NM = #{username}
     , USER_EML                         = #{userEml}
     , USER_CONT_1                           = #{userCont1}
     , USER_CONT_2                           = #{userCont2}
     , USER_CONT_3                           = #{userCont3}
     , USER_HP_1                            = #{userHp1}
     , USER_HP_2                            = #{userHp2}
     , USER_HP_3                            = #{userHp3}
     , USER_AUTH_CD                  = #{userAuthCd}
     , DEL_YN                      = 'N'
     , mdfcn_user_seq                  = #{loginUserSeq}
     , mdfcn_dt                      = CURRENT_TIMESTAMP
     , mdfcn_ip						= #{loginUserIp}

     , USER_PW						= #{newPassword}

WHERE USER_SEQ = #{userSeq}
